/* Tessellate Type Scale: Golden Ratio (1.618) */
:root {
  --font-heading: Geist, Inter, system-ui, sans-serif;
  --font-body: Geist, Inter, system-ui, sans-serif;
  --font-mono: Geist Mono, JetBrains Mono, monospace;
  --font-numeric: tabular-nums slashed-zero;

  --font-size-h1: clamp(36px, 7.64vw, 110px);
  --font-size-h2: clamp(30px, 4.72vw, 68px);
  --font-size-h3: clamp(24px, 2.92vw, 42px);
  --font-size-h4: clamp(20px, 1.81vw, 26px);
  --font-size-body: 16px;
  --font-size-small: 10px;
}
